// Función recursiva para calcular el factorial
int factorial(int n) {
    // Caso base
    if (n <= 1) return 1;

    // Llamada recursiva
    return n * factorial(n - 1);
}

int main() {
    int numero;
    cout << "Ingresa un número: "; 
    cin >> numero;

    cout << "factorial(" << numero << ") = "
         << factorial(numero) << endl;

    // Traza para n=5:
    // factorial(5) = 5 * factorial(4)
    //              = 5 * 4 * factorial(3)
    //              = 5 * 4 * 3 * factorial(2)
    //              = 5 * 4 * 3 * 2 * factorial(1)
    //              = 5 * 4 * 3 * 2 * 1 = 120

    return 0;
}

