// Algoritmo de ordenamiento burbuja
void burbuja(vector<int>& v) {
    int n = v.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (v[j] > v[j + 1]) {
                // Intercambiar elementos
                int temp = v[j];
                v[j]     = v[j + 1];
                v[j + 1] = temp;
            }
        }
    }
}

int main() {
    vector<int> numeros = {5, 2, 8, 1, 4};

    cout << "Antes: ";
    for (int x : numeros) cout << x << " ";
    cout << endl;

