// Retorna el índice donde se encuentra la clave, o -1 si no existe
int busquedaLineal(const vector<int>& v, int clave) {
    for (int i = 0; i < (int)v.size(); i++) {
        if (v[i] == clave) {
            return i;    // encontrado en posición i
        }
    }
    return -1;           // no encontrado
}

int main() {
    vector<int> datos = {15, 3, 9, 42, 7, 18, 5};

    cout << "Vector: ";
    for (int x : datos) cout << x << " ";
    cout << endl;

    int clave;
    cout << "Buscar: ";
    cin >> clave;

    int pos = busquedaLineal(datos, clave);

    if (pos != -1) {
        cout << "Encontrado en posición: " << pos << endl;
    } else {
        cout << "Elemento no encontrado." << endl;
    }

