public class Persona {
    // Atributos privados (encapsulación)
    private String nombre;
    private int edad;

    // Constructor: recibe los datos iniciales del objeto
    public Persona(String nombre, int edad) {
        this.nombre = nombre;   // 'this' diferencia el atributo del parámetro
        this.edad   = edad;
    }

    // Getters: permiten leer atributos privados
    public String getNombre() { return nombre; }
    public int    getEdad()   { return edad; }

    // Setter: permite modificar la edad con validación
    public void setEdad(int edad) {
        if (edad >= 0) {        // protege el atributo de valores inválidos
            this.edad = edad;
        }
    }

    // Método de negocio
    public boolean esMayorDeEdad() {
        return edad >= 18;
    }

    // Punto de entrada del programa
    public static void main(String[] args) {
        Persona p = new Persona("María", 21);

        System.out.println("Nombre:    " + p.getNombre());
        System.out.println("Edad:      " + p.getEdad());
        System.out.println("¿Mayor?:   " + p.esMayorDeEdad());
    }
}

// ╭───────────────────────────────────────────────────╮
// │  Búsqueda binaria sobre una lista ordenada (Java) │
// ╰───────────────────────────────────────────────────╯
//
// Pre-condición: la lista DEBE estar ordenada de menor a mayor.
// La búsqueda binaria divide el rango a la mitad en cada paso.
// Complejidad: O(log n), mucho mejor que la lineal O(n).

import java.util.ArrayList;
import java.util.Arrays;

public class BusquedaBinaria {

    // Retorna el índice del elemento o -1 si no existe
    public static int buscar(ArrayList<Integer> lista, int clave) {
        int inicio = 0;
        int fin    = lista.size() - 1;

        while (inicio <= fin) {
            int medio = (inicio + fin) / 2;
            int valor = lista.get(medio);

            if (valor == clave) {
                return medio;            // encontrado
            } else if (valor < clave) {
                inicio = medio + 1;      // buscar en la mitad superior
            } else {
                fin    = medio - 1;      // buscar en la mitad inferior
            }
        }
        return -1;                       // no encontrado
    }

    public static void main(String[] args) {
        ArrayList<Integer> datos = new ArrayList<>(
            Arrays.asList(2, 5, 8, 12, 16, 23, 38, 56, 72, 91)
        );

        int clave = 23;
        int pos   = buscar(datos, clave);

        if (pos != -1) {
            System.out.println("Encontrado en índice: " + pos);
        } else {
            System.out.println("No encontrado.");
        }
    }
}
